values ('bbbb0003-0000-4000-8000-000000000007', 'en', null, 'Personal Financial Literacy', 'A practical first course in managing money — budgeting, saving, borrowing, and investing — for everyday life. Built from openly-licensed OER Commons personal-finance material (CC BY). This is financial education for learning, not personalized financial advice.', null, 'daily_life', 7, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000007', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The 50/30/20 guideline suggests spending about 50% of take-home pay on…","options":["needs like housing and food","wants like dining out","savings and debt payoff","entertainment only"],"answer":0,"explanation":"In 50/30/20, half goes to needs, 30% to wants, 20% to savings/debt — see ''Budgeting''."},{"prompt":"A basic emergency fund typically covers…","options":["10 years of income","3 to 6 months of essential expenses","one week of pay","nothing — it''s optional"],"answer":1,"explanation":"The common target is 3-6 months of essentials — see ''Saving''."},{"prompt":"Compound interest means you earn interest on…","options":["only your original deposit","your deposit plus previously earned interest","only bank fees","nothing until year 10"],"answer":1,"explanation":"Interest earns interest — that''s the whole idea. See ''Compound interest''."},{"prompt":"The single biggest factor in a typical credit score is…","options":["your age","your payment history","your ZIP code","the color of your card"],"answer":1,"explanation":"Payment history is roughly 35% of a FICO score — see ''Credit''."},{"prompt":"Money you can spend anytime with a debit card usually sits in a…","options":["checking account","30-year bond","stock index fund","safe-deposit box"],"answer":0,"explanation":"Checking is for everyday spending; savings is for holding cash."},{"prompt":"Spreading money across many investments to lower risk is called…","options":["inflation","diversification","withholding","a deductible"],"answer":1,"explanation":"Diversification reduces the impact of any one loss — see ''Investing''."},{"prompt":"Under a progressive income tax, higher income is generally…","options":["taxed at higher rates on the top portion","completely tax-free","taxed less than low income","ignored by the government"],"answer":0,"explanation":"Only the income in each higher bracket is taxed at that bracket''s rate."},{"prompt":"An insurance deductible is…","options":["the amount you pay before coverage kicks in","a type of stock","free money from the insurer","your credit score"],"answer":0,"explanation":"You cover costs up to the deductible; insurance covers the rest per the policy."}]}'::jsonb, null, 10),
  (2, 'Budgeting and tracking spending', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build a simple monthly budget and explain why tracking spending matters. Warm-up: from the diagnostic, what three buckets does the 50/30/20 rule split your money into?"},{"heading":"The idea","text":"A *budget* is just a plan that matches money coming in to money going out. A popular starting template is *50/30/20*: about 50% of take-home pay for *needs* (housing, groceries, utilities, minimum debt payments), 30% for *wants* (dining out, subscriptions), and 20% for *savings and extra debt payoff*. Example: if your take-home pay is $3,200 a month, that''s $1,600 for needs, $960 for wants, and $640 for savings and debt. *Tracking* — writing down what you actually spend — is what turns the plan into reality, because most people underestimate small, frequent purchases."},{"heading":"Worked example","text":"Say take-home pay is $2,500/month. Needs = 50% × $2,500 = $1,250. Wants = 30% × $2,500 = $750. Savings/debt = 20% × $2,500 = $500. The three add back to $2,500. Now suppose tracking shows rent is $1,400 — already above the $1,250 needs cap. The budget still has to balance, so something must give: trim wants, or find cheaper housing."},{"heading":"Your turn","text":"Take-home pay is $2,000/month. (1) How much for needs? (2) How much for wants? (3) How much for savings/debt? (4) If rent alone is $1,100, does it fit inside the needs bucket? Answers: (1) $1,000; (2) $600; (3) $400; (4) No — $1,100 is more than the $1,000 needs cap, so you''d trim elsewhere."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating 50/30/20 as a law rather than a starting point — adjust the ratios to your life. Mistake: budgeting once and never tracking, so small daily spending quietly breaks the plan. Exit: (a) Which bucket do minimum debt payments belong in? (b) Why track spending at all? Answers: needs; because actual spending, especially small purchases, usually differs from the plan."}]}'::jsonb, '50/30/20: needs / wants / savings & debt.', 12),
  (3, 'Saving and emergency funds', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Set an emergency-fund target and estimate how long it takes to reach it. Warm-up: roughly how many months of expenses does a basic emergency fund cover?"},{"heading":"The idea","text":"An *emergency fund* is cash set aside for unexpected costs — a car repair, a medical bill, a lost job — so you don''t have to borrow at high interest. The common target is *3 to 6 months of essential expenses* (not total spending, just the needs). Keep it somewhere safe and reachable, like a savings account, not invested in the stock market where its value can drop right when you need it. Example: if your essential costs are $1,800/month, a 3-month fund is $5,400 and a 6-month fund is $10,800."},{"heading":"Worked example","text":"Essentials are $1,800/month, so a 3-month fund = 3 × $1,800 = $5,400. If you save $300/month toward it, months needed = $5,400 ÷ $300 = 18 months. Save more per month and the timeline shrinks; automating the transfer on payday makes it far more likely to actually happen."},{"heading":"Your turn","text":"Essential costs are $2,000/month. (1) What is a 3-month fund? (2) A 6-month fund? (3) Saving $250/month, how long to reach the 3-month fund? (4) If a $500 gift is added up front, how long for the rest at $250/month? Answers: (1) $6,000; (2) $12,000; (3) $6,000 ÷ $250 = 24 months; (4) ($6,000 − $500) ÷ $250 = $5,500 ÷ $250 = 22 months."},{"heading":"Common mistakes & exit ticket","text":"Mistake: sizing the fund on total spending instead of essential expenses, making the goal feel impossible. Mistake: parking the fund in volatile investments. Exit: (a) A fund covers 3-6 months of what kind of expenses? (b) Where should it live? Answers: essential expenses; a safe, accessible account such as savings."}]}'::jsonb, 'Emergency fund = 3-6 months of essential expenses.', 11),
  (4, 'Compound interest and the time value of money', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute compound growth and explain why time matters more than timing. Warm-up: does compound interest pay you on your deposit only, or on the interest too?"},{"heading":"The idea","text":"The *time value of money* says a dollar today is worth more than a dollar later, because today''s dollar can earn interest. With *compound interest*, each period''s interest is added to the balance, so future interest is earned on a larger amount. For yearly compounding the balance is A = P(1 + r)^t, where P is the starting amount, r the annual rate as a decimal, and t the number of years. Example: $1,000 at 6% for one year becomes $1,000 × 1.06 = $1,060; the next year earns 6% on $1,060, not on $1,000."},{"heading":"Worked example","text":"Put $1,000 at 6% compounded annually for 10 years: A = $1,000 × 1.06^10 = $1,790.85, so you earned $790.85. The first year added only $60, but later years add more because interest compounds. Two shortcuts: the *Rule of 72* estimates doubling time as 72 ÷ rate, so at 6% money doubles in about 72 ÷ 6 = 12 years. And compound beats *simple* interest: $1,000 at 10% for 3 years is $1,300 simple (1,000 × 0.10 × 3 = $300 interest) but $1,000 × 1.10^3 = $1,331 compounded — $31 more, a gap that widens over decades."},{"heading":"Your turn","text":"(1) $2,000 at 5% compounded annually for 2 years — what''s the balance? (2) Using the Rule of 72, how long to double at 8%? (3) Simple interest on $500 at 4% for 3 years — how much interest, and what total? (4) $1,000 at 7% compounded annually for 10 years — about how much? Answers: (1) $2,000 × 1.05^2 = $2,000 × 1.1025 = $2,205; (2) 72 ÷ 8 = 9 years; (3) $500 × 0.04 × 3 = $60 interest, $560 total; (4) $1,000 × 1.07^10 ≈ $1,967.15."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a higher rate matters more than starting early — time in the market usually beats a slightly better rate. Mistake: forgetting that compounding works against you on debt too, where unpaid interest is added to what you owe. Exit: (a) In A = P(1 + r)^t, what does r represent? (b) Rule-of-72 doubling time at 9%? Answers: the annual rate as a decimal; about 72 ÷ 9 = 8 years."}]}'::jsonb, 'A = P(1 + r)^t — interest earns interest over time.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Under 50/30/20, take-home pay of $2,000 leaves how much for savings and debt?","options":["$200","$400","$600","$1,000"],"answer":1,"explanation":"20% × $2,000 = $400."},{"prompt":"A 3-month emergency fund for $1,500/month in essentials is…","options":["$1,500","$3,000","$4,500","$18,000"],"answer":2,"explanation":"3 × $1,500 = $4,500."},{"prompt":"$1,000 at 6% compounded annually for 10 years grows to about…","options":["$1,060","$1,600","$1,791","$6,000"],"answer":2,"explanation":"$1,000 × 1.06^10 = $1,790.85."},{"prompt":"Using the Rule of 72, money doubles at 8% in about…","options":["3 years","9 years","24 years","72 years"],"answer":1,"explanation":"72 ÷ 8 = 9 years."},{"prompt":"Compared with simple interest, compound interest over many years earns…","options":["less","exactly the same","more","nothing"],"answer":2,"explanation":"Interest earning interest pulls ahead over time."},{"prompt":"The main point of tracking spending is to…","options":["see where your money actually goes","instantly raise your salary","avoid all taxes","pick winning stocks"],"answer":0,"explanation":"Tracking reveals the gap between the plan and reality."}]}'::jsonb, null, 8),
  (6, 'Credit, credit scores, and debt', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a credit score measures and calculate credit utilization. Warm-up: what is the single biggest factor in a typical credit score?"},{"heading":"The idea","text":"*Credit* is borrowed money you promise to repay, often with interest measured as an *APR* (annual percentage rate). A *credit score* — commonly on a 300 to 850 scale — summarizes how reliably you repay. The two largest factors are *payment history* (about 35%, so on-time payments matter most) and *amounts owed*, especially *credit utilization*: your balance divided by your credit limit. A common guideline is to keep utilization under about 30%. Example: on a card with a $1,000 limit, that means keeping the balance under $300."},{"heading":"Worked example","text":"A card has a $2,000 limit and a $600 balance, so utilization = $600 ÷ $2,000 = 30%. Now suppose you instead carry a $2,000 balance at 22% APR for a year: interest is roughly $2,000 × 0.22 = $440, about $36.67 a month, and paying only the minimum stretches payoff for years while interest compounds on the unpaid amount. That is compound interest working against you."},{"heading":"Your turn","text":"(1) Limit $1,000, balance $250 — what''s the utilization? (2) Limit $1,000, balance $500 — utilization, and is it within the guideline? (3) To keep a $500 balance under 30% utilization, at least what limit do you need? (4) Which factor weighs most in a typical score? Answers: (1) $250 ÷ $1,000 = 25%; (2) 50%, above the ~30% guideline; (3) $500 ÷ 0.30 ≈ $1,667; (4) payment history."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing carrying a balance ''builds credit'' — it just costs interest; paying on time and in full is what helps. Mistake: closing an old card without thinking, which can raise your utilization by cutting total available credit. Exit: (a) Utilization equals balance divided by what? (b) Which score factor is largest? Answers: your credit limit; payment history."}]}'::jsonb, 'Keep credit utilization under about 30%.', 12),
  (7, 'Investing basics: stocks, bonds, and index funds', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell stocks, bonds, and index funds apart and explain how diversification lowers risk. Warm-up: what word describes spreading money across many investments?"},{"heading":"The idea","text":"A *stock* is part-ownership of a company — higher potential return but higher risk. A *bond* is a loan to a government or company that pays interest — generally lower risk and lower return. An *index fund* holds a broad basket of assets to track a whole market (say, 500 large companies) at low cost. *Diversification* — owning many things — means no single failure sinks you. The core trade-off: higher expected return almost always comes with more risk and more ups and downs along the way."},{"heading":"Worked example","text":"Put $10,000 in one company''s stock and, if it drops 50%, you''re left with $5,000. Spread the same $10,000 across an index of 500 companies and one company failing barely moves the total. Costs matter too: over 30 years, a $10,000 investment growing about 7% a year ends near $57,000 with a 1% annual fee but closer to $75,000 with a 0.05% fee — roughly $18,000 lost to fees, just from a fraction of a percent."},{"heading":"Your turn","text":"(1) Rank from lowest to highest typical risk: single-company stock, government bond, broad index fund. (2) Which spreads risk across many companies at low cost? (3) $10,000 in one stock that falls 50% leaves how much? (4) Higher expected return usually comes with what? Answers: (1) government bond, then index fund, then single stock; (2) an index fund; (3) $5,000; (4) higher risk."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing volatility with permanent loss — broad markets swing but have historically recovered over long periods. Mistake: ignoring fees because they look tiny; small percentages compound into large amounts over decades. Exit: (a) Which is usually lower risk, a bond or a single stock? (b) What does an index fund give you cheaply? Answers: a bond; broad diversification."}]}'::jsonb, 'Higher expected return generally means higher risk.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"budget","translation":"a plan that matches income to spending and saving over a set period","example":"Her monthly budget puts 20% toward savings."},{"term":"emergency fund","translation":"cash set aside for unexpected costs, usually 3 to 6 months of essential expenses","example":"The car repair came out of his emergency fund, not a credit card."},{"term":"compound interest","translation":"interest earned on both the original amount and the interest already added","example":"Thanks to compound interest, the account grew faster each year."},{"term":"APR","translation":"annual percentage rate — the yearly cost of borrowing, including interest","example":"A card with a 22% APR is expensive to carry a balance on."},{"term":"credit score","translation":"a number, often 300 to 850, summarizing how reliably someone repays debt","example":"Paying every bill on time slowly raised her credit score."},{"term":"index fund","translation":"an investment holding a broad basket of assets to track a market index at low cost","example":"He invests through a low-fee index fund instead of picking single stocks."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Credit utilization is your balance divided by your…","options":["income","credit limit","age","savings"],"answer":1,"explanation":"Utilization = balance ÷ credit limit."},{"prompt":"A common guideline is to keep credit utilization below about…","options":["30%","90%","100%","5%"],"answer":0,"explanation":"Under ~30% is a widely used rule of thumb."},{"prompt":"Which of these typically carries the lowest risk?","options":["a single startup''s stock","a government bond","a lottery ticket","one speculative coin"],"answer":1,"explanation":"Government bonds are generally lower risk than individual stocks."},{"prompt":"An index fund is attractive largely because it offers…","options":["guaranteed profit","broad diversification at low cost","zero risk","secret stock tips"],"answer":1,"explanation":"It spreads risk cheaply across a whole market."},{"prompt":"Payroll tax withholding means income tax is…","options":["taken from each paycheck","paid only at age 65","completely optional","against the law"],"answer":0,"explanation":"Employers withhold estimated tax from each paycheck."},{"prompt":"An insurance premium is…","options":["the regular payment you make for coverage","a stock dividend","your credit score","a guaranteed tax refund"],"answer":0,"explanation":"The premium is what you pay to keep a policy active."}]}'::jsonb, null, 8),
  (10, 'Applied project: build your own monthly budget + savings plan', 'writing', '{"sections":[{"heading":"The task","text":"Create a realistic one-month budget and a savings plan you could actually follow. Use your own numbers, or realistic made-up figures if you''d rather not share real ones. This is a planning exercise, not financial advice — you''re practicing the method."},{"heading":"Milestones","text":"1) Write your monthly take-home income. 2) Split it with 50/30/20 (needs / wants / savings & debt), then adjust the percentages to fit your real costs so the buckets still add up to your income. 3) Estimate your essential monthly expenses and set an emergency-fund target of 3-6 months of them. 4) Choose a monthly savings amount and compute the timeline: target ÷ monthly savings = months to reach it. 5) State one longer-term goal and, using A = P(1 + r)^t, estimate what a lump sum would grow to at a chosen rate."},{"heading":"Self-check rubric","text":"✔ The three budget buckets add up to your income. ✔ Your emergency-fund target is based on essential expenses, not total spending. ✔ Your savings timeline shows the actual math (target ÷ monthly amount). ✔ Your growth estimate uses the compound formula correctly. If all four hold, you have a budget and savings plan you could put into action this month."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000007' and l.position = v.pos
);
